/* ---------- 全局搜索面板（⌘K） ---------- */
function initSearch(){
  const idx = buildSearchIndex();
  const mask = document.createElement('div'); mask.className='search-mask';
  mask.innerHTML = '<div class="search-box"><input type="text" placeholder="搜索文章、命令、实验… (⌘K)" autocomplete="off"><div class="search-res"></div></div>';
  document.body.appendChild(mask);
  const inp = mask.querySelector('input');
  const res = mask.querySelector('.search-res');
  let sel = 0, filtered = [];
  function render(q){
    q = q.trim().toLowerCase();
    filtered = q ? idx.filter(x=>(x.t+x.d+x.p).toLowerCase().includes(q)).slice(0,20) : idx.slice(0,12);
    sel = 0;
    if(filtered.length===0){ res.innerHTML='<div class="search-empty">🔍 没有找到相关结果，换个关键词试试？</div>'; return; }
    const hl = (t)=> q ? t.replace(new RegExp('('+q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi'),'<em>$1</em>') : t;
    res.innerHTML = filtered.map((x,i)=>`<div class="search-item${i===0?' sel':''}" data-u="${x.u}"><div class="si-t">${hl(x.t)}</div><div class="si-p">${x.p} · ${x.d||''}</div></div>`).join('');
  }
  function open(){ mask.classList.add('show'); inp.value=''; render(''); setTimeout(()=>inp.focus(),50); }
  function close(){ mask.classList.remove('show'); }
  function go(){ const it=filtered[sel]; if(it){ close(); location.href=it.u; } }
  inp.addEventListener('input', ()=>render(inp.value));
  inp.addEventListener('keydown', e=>{
    if(e.key==='ArrowDown'){ e.preventDefault(); sel=Math.min(sel+1,filtered.length-1); updateSel(); }
    else if(e.key==='ArrowUp'){ e.preventDefault(); sel=Math.max(sel-1,0); updateSel(); }
    else if(e.key==='Enter'){ e.preventDefault(); go(); }
    else if(e.key==='Escape'){ close(); }
  });
  function updateSel(){
    [...res.children].forEach((el,i)=>{
      el.classList.toggle('sel',i===sel);
      if(i===sel) el.scrollIntoView({block:'nearest'});
    });
  }
  res.addEventListener('mouseover', e=>{
    const it = e.target.closest('.search-item'); if(!it) return;
    sel = [...res.children].indexOf(it); updateSel();
  });
  res.addEventListener('click', e=>{
    const it = e.target.closest('.search-item'); if(!it) return;
    close(); location.href = it.dataset.u;
  });
  mask.addEventListener('click', e=>{ if(e.target===mask) close(); });
  document.addEventListener('keydown', e=>{
    if((e.metaKey||e.ctrlKey) && e.key.toLowerCase()==='k'){ e.preventDefault(); mask.classList.contains('show')?close():open(); trackSearch(); }
    if(e.key==='Escape' && mask.classList.contains('show')) close();
    if(e.key==='/' && !mask.classList.contains('show') && !e.target.closest('input,textarea')){ e.preventDefault(); open(); trackSearch(); }
  });
  document.querySelectorAll('.search-btn,[data-search]').forEach(b=>b.addEventListener('click',()=>{open();trackSearch();}));
}

/* ---------- 代码块增强：语言检测 + 复制增强 ---------- */
function initCodeCopy(){
  document.querySelectorAll('.code-block').forEach((block,idx)=>{
    // 自动检测语言标签
    if(!block.querySelector('.code-lang')){
      const code = block.querySelector('pre code, pre');
      const text = code?code.textContent.slice(0,200):'';
      let lang='code';
      if(/^(\$ |# |ros|catkin|sudo|apt|cd |ls |mkdir|echo|source|chmod|git )/m.test(text)) lang='bash';
      else if(/^#include|int main|void |class |public:|std::/m.test(text)) lang='cpp';
      else if(/^import |def |from |print\(|class .*:/m.test(text)) lang='python';
      else if(/<\?xml|<launch|<node |<package/.test(text)) lang='xml';
      else if(/^name:|find_package|cmake_minimum|add_executable|target_link/m.test(text)) lang='cmake';
      else if(/^services:|topics:|actions:|geometry_msgs|nav_msgs|sensor_msgs/m.test(text)) lang='msg';
      if(lang!=='code'){
        const tag=document.createElement('span'); tag.className='code-lang'; tag.textContent=lang; block.appendChild(tag);
      }
    }
    // 复制按钮
    if(!block.querySelector('.code-copy')){
      const btn = document.createElement('button'); btn.className='code-copy'; btn.innerHTML='<span class="cc-icon">📋</span><span>复制</span>';
      btn.addEventListener('click',()=>{
        const code = block.querySelector('pre code') || block.querySelector('pre');
        if(!code) return;
        let text = code.textContent;
        // 过滤终端提示符 $ 和 #
        text = text.replace(/^(\s*)(\$ |# )/gm, '$1');
        navigator.clipboard.writeText(text).then(()=>{
          btn.innerHTML='<span class="cc-icon">✓</span><span>已复制</span>'; btn.classList.add('copied');
          setTimeout(()=>{btn.innerHTML='<span class="cc-icon">📋</span><span>复制</span>';btn.classList.remove('copied');},1800);
        }).catch(()=>{
          // fallback
          const ta=document.createElement('textarea'); ta.value=text; document.body.appendChild(ta); ta.select();
          document.execCommand('copy'); ta.remove();
          btn.innerHTML='<span class="cc-icon">✓</span><span>已复制</span>'; btn.classList.add('copied');
          setTimeout(()=>{btn.innerHTML='<span class="cc-icon">📋</span><span>复制</span>';btn.classList.remove('copied');},1800);
        });
      });
      block.appendChild(btn);
    }
  });
}

