/* ---------- 环境 drone 音效（子页面轻量版） ---------- */
function initSound(){
  const btn = document.getElementById('sndbtn'); if(!btn) return;
  let ac=null, nodes=null;
  function start(){
    ac = ac||new (window.AudioContext||window.webkitAudioContext)();
    if(ac.state==='suspended') ac.resume();
    const out=ac.createGain(); out.gain.value=0; out.connect(ac.destination);
    const mix=ac.createGain(); mix.gain.value=.12;
    const flt=ac.createBiquadFilter(); flt.type='lowpass'; flt.frequency.value=200; flt.Q.value=2;
    const oscs=[];
    [['sine',55,0],['triangle',82.41,4],['sine',110,-3]].forEach(cfg=>{
      const o=ac.createOscillator(); o.type=cfg[0]; o.frequency.value=cfg[1]; o.detune.value=cfg[2];
      o.connect(mix); o.start(); oscs.push(o);
    });
    const lfo=ac.createOscillator(); lfo.frequency.value=.05;
    const lfoG=ac.createGain(); lfoG.gain.value=100;
    lfo.connect(lfoG); lfoG.connect(flt.frequency); lfo.start(); oscs.push(lfo);
    mix.connect(flt); flt.connect(out);
    out.gain.linearRampToValueAtTime(.04,ac.currentTime+2);
    nodes={out,oscs};
  }
  function stop(){
    if(!nodes) return;
    nodes.out.gain.linearRampToValueAtTime(0,ac.currentTime+.8);
    setTimeout(()=>{try{nodes.out.disconnect();}catch(e){} nodes=null;},900);
  }
  btn.addEventListener('click',()=>{
    const on=!nodes;
    if(on)start(); else stop();
    btn.setAttribute('aria-pressed',String(on));
    btn.textContent=on?'🔊':'🔇';
    btn.classList.toggle('on',on);
    if(on) trackSound();
  });
}

/* ---------- 首访 Toast ---------- */
function initToast(key){
  const t = document.getElementById('toast'); if(!t) return;
  let seen=false; try{seen=!!localStorage.getItem(key);}catch(e){}
  if(seen||location.hash) return;
  setTimeout(()=>t.classList.add('show'),1500);
  function dismiss(){ if(!t.classList.contains('show'))return; t.classList.remove('show'); try{localStorage.setItem(key,'1');}catch(e){} }
  const btn=document.getElementById('toast-x'); if(btn)btn.addEventListener('click',dismiss);
  setTimeout(dismiss,12000);
}

