/* ---------- 趣味彩蛋：点击粒子爆发 ---------- */
function initClickBurst(){
  document.addEventListener('click', e=>{
    if(e.target.closest('button,a,input,textarea,.code-block,.search-mask,.trouble-q,.cmd,.cmd-line,.drawer-mask')) return;
    const x=e.clientX, y=e.clientY;
    const colors=['#22d3ee','#2dd4bf','#f59e0b','#a78bfa','#fb7185','#4ade80'];
    for(let i=0;i<8;i++){
      const p=document.createElement('div');
      const ang=Math.random()*Math.PI*2, dist=20+Math.random()*40;
      p.style.cssText=`position:fixed;left:${x}px;top:${y}px;width:6px;height:6px;border-radius:50%;pointer-events:none;z-index:9999;background:${colors[i%colors.length]};transition:.6s cubic-bezier(.2,.9,.3,1.15);opacity:1;transform:translate(-50%,-50%)`;
      document.body.appendChild(p);
      requestAnimationFrame(()=>{
        p.style.transform=`translate(calc(-50% + ${Math.cos(ang)*dist}px), calc(-50% + ${Math.sin(ang)*dist}px)) scale(0)`;
        p.style.opacity='0';
      });
      setTimeout(()=>p.remove(),700);
    }
  });
}

/* ---------- 成就系统 ---------- */
const ACH_KEY='ros1-achievements-v1';
const ACHIEVEMENTS=[
  {id:'first-step',name:'启程',desc:'阅读第一篇文章',icon:'🌱',check:s=>s.readCount>=1},
  {id:'explorer',name:'探索者',desc:'阅读5篇文章',icon:'🔭',check:s=>s.readCount>=5},
  {id:'scholar',name:'学者',desc:'阅读10篇文章',icon:'📚',check:s=>s.readCount>=10},
  {id:'master',name:'ROS大师',desc:'阅读全部23篇文章',icon:'🏆',check:s=>s.readCount>=23},
  {id:'commander',name:'指挥官',desc:'打开知识星图',icon:'🌌',check:s=>s.visitedMap},
  {id:'experimenter',name:'实验家',desc:'进入动手实验页面',icon:'🔬',check:s=>s.visitedExp},
  {id:'commander-cmd',name:'终端指挥官',desc:'使用命令速查',icon:'⚡',check:s=>s.visitedCmd},
  {id:'detective',name:'侦探',desc:'查看错误排查',icon:'🔍',check:s=>s.visitedTrouble},
  {id:'searcher',name:'搜索专家',desc:'使用⌘K搜索3次',icon:'🔎',check:s=>s.searchCount>=3},
  {id:'marathon',name:'马拉松',desc:'单篇文章阅读到底部',icon:'🏃',check:s=>s.readToEnd},
  {id:'sound-on',name:'沉浸模式',desc:'开启环境音效',icon:'🔊',check:s=>s.soundOn},
  {id:'konami',name:'黑客入侵',desc:'输入Konami秘籍',icon:'🕵️',check:()=>false},
];
function getAch(){ try{return JSON.parse(localStorage.getItem(ACH_KEY)||'{}');}catch(e){return {};} }
function setAch(k,v){ const a=getAch(); a[k]=v; try{localStorage.setItem(ACH_KEY,JSON.stringify(a));}catch(e){} }
function unlockAchievement(a){
  const ach=getAch(); if(ach[a.id]) return;
  setAch(a.id, Date.now());
  const toast=document.createElement('div');
  toast.className='ach-toast';
  toast.innerHTML=`<div class="ach-icon">${a.icon}</div><div><div class="ach-name">🏅 成就解锁！</div><div class="ach-txt"><b>${a.name}</b> — ${a.desc}</div></div>`;
  document.body.appendChild(toast);
  requestAnimationFrame(()=>toast.classList.add('show'));
  setTimeout(()=>{toast.classList.remove('show');setTimeout(()=>toast.remove(),500);},4500);
}
function trackVisit(){
  const page=location.pathname.split('/').pop() || 'index.html';
  const a=getAch();
  if(page==='map.html'&&!a['commander']){setAch('commander',Date.now());unlockAchievement(ACHIEVEMENTS.find(x=>x.id==='commander'));}
  if(page==='experiments.html'&&!a['experimenter']){setAch('experimenter',Date.now());unlockAchievement(ACHIEVEMENTS.find(x=>x.id==='experimenter'));}
  if(page==='commands.html'&&!a['commander-cmd']){setAch('commander-cmd',Date.now());unlockAchievement(ACHIEVEMENTS.find(x=>x.id==='commander-cmd'));}
  if(page==='troubleshoot.html'&&!a['detective']){setAch('detective',Date.now());unlockAchievement(ACHIEVEMENTS.find(x=>x.id==='detective'));}
}
function checkAchievements(){
  const read=readSet();
  const stats={readCount:read.size,searchCount:window.__searchCount||0};
  Object.assign(stats,getAch());
  ACHIEVEMENTS.forEach(a=>{ if(!getAch()[a.id] && a.check(stats)){ setAch(a.id,Date.now()); unlockAchievement(a); } });
}

/* ---------- Konami Code 彩蛋（↑↑↓↓←→←→BA） ---------- */
function initKonami(){
  const seq=[38,38,40,40,37,39,37,39,66,65]; let pos=0;
  document.addEventListener('keydown',e=>{
    if(e.keyCode===seq[pos] || e.key===seq[pos]){
      pos++;
      if(pos===seq.length){
        pos=0;
        if(!getAch()['konami']){setAch('konami',Date.now());unlockAchievement(ACHIEVEMENTS.find(x=>x.id==='konami'));}
        document.body.style.animation='matrix .1s infinite alternate';
        const msg=document.createElement('div');
        msg.style.cssText='position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);z-index:10000;font-family:monospace;font-size:clamp(18px,4vw,28px);color:#4ade80;text-shadow:0 0 30px #4ade80,0 0 60px #4ade80;font-weight:700;pointer-events:none;letter-spacing:4px;text-align:center';
        msg.textContent='> ACCESS GRANTED <';
        document.body.appendChild(msg);
        // 额外的彩蛋：屏幕上散落一些0和1
        for(let i=0;i<30;i++){
          const bit=document.createElement('div');
          bit.textContent=Math.random()>.5?'0':'1';
          bit.style.cssText=`position:fixed;left:${Math.random()*100}vw;top:${Math.random()*100}vh;color:#4ade80;font-family:monospace;font-size:${12+Math.random()*20}px;opacity:${.3+Math.random()*.5};z-index:9998;pointer-events:none;animation:matrixbit ${1+Math.random()*2}s linear forwards`;
          document.body.appendChild(bit);
          setTimeout(()=>bit.remove(),3000);
        }
        setTimeout(()=>{document.body.style.animation='';msg.remove();},3500);
      }
    }else{pos=0;}
  });
}

/* ---------- ROS 趣味冷知 ---------- */
const FUN_FACTS=[
  'ROS 的前身是斯坦福大学的 STAIR 项目，2007年由 Willow Garage 接手孵化',
  'turtlesim 里的小海龟是每个ROS开发者的第一个机器人伙伴，它的名字叫 "turtle1"',
  'NASA 的 VIPER 月球车用到了ROS相关技术，ROS真的去过太空！',
  '"ROS" 这个名字差点叫 "switchyard"（中转站），因为它的核心是消息路由',
  '全球超过一半的服务机器人研究论文使用ROS作为实验平台',
  'ROS 的 logo 是九只机器人围成字母"R"，象征分布式节点协作',
  'roscore 启动时的 SUMMARY 里，每一行都是一个节点在向Master报到',
  '百度 Apollo 和 Autoware 自动驾驶平台都基于 ROS 构建',
  'TF 坐标变换系统最初是为了让 PR2 机器人能抓杯子而设计的',
  'ROS 2 最大的进步是取消了 roscore——节点可以点对点直连',
  'ROS 教程里的 listener 示例，全世界的ROS开发者都敲过至少一遍',
  'ROS 节点通信协议是 XMLRPC（介绍认识）+ TCP/UDP（传输数据）',
  'catkin_make 编译时会自动生成依赖关系图，比手写Makefile聪明多了',
  'rosbag 就像机器人的"录像机"，能录下所有传感器数据反复回放',
];
let factTimeout;
function showFunFact(){
  const fact=FUN_FACTS[Math.floor(Math.random()*FUN_FACTS.length)];
  const el=document.createElement('div');
  el.className='fun-fact';
  el.innerHTML=`<span class="ff-ic">💡</span><span class="ff-txt">冷知识：${fact}</span><button class="ff-x" aria-label="关闭">✕</button>`;
  document.body.appendChild(el);
  requestAnimationFrame(()=>el.classList.add('show'));
  const dismiss=()=>{el.classList.remove('show');setTimeout(()=>el.remove(),500);clearTimeout(factTimeout);};
  el.querySelector('.ff-x').onclick=dismiss;
  el.onclick=dismiss;
  factTimeout=setTimeout(dismiss,15000);
}

/* ---------- 随机探索按钮 ---------- */
function initRandomExplore(){
  document.querySelectorAll('[data-random]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const arts=window.__ARTICLES__||{};
      const ids=Object.keys(arts).filter(k=>!arts[k].hidden);
      if(ids.length===0) return;
      const unread=ids.filter(k=>!isRead('article.html?id='+k));
      const pool=unread.length>0?unread:ids;
      const pick=pool[Math.floor(Math.random()*pool.length)];
      location.href='article.html?id='+pick;
    });
  });
}

/* ---------- 阅读到底检测 ---------- */
function initReadToEnd(){
  let reached=false;
  function check(){
    if(reached) return;
    const h=document.documentElement;
    if(h.scrollTop + h.clientHeight >= h.scrollHeight - 120){
      reached=true;
      const a=getAch();
      if(!a['marathon']){setAch('marathon',Date.now());unlockAchievement(ACHIEVEMENTS.find(x=>x.id==='marathon'));}
    }
  }
  window.addEventListener('scroll',check,{passive:true});
}

/* ---------- 阅读位置记忆 ---------- */
function initScrollMemory(){
  const key='ros1-scroll-'+location.pathname;
  try{
    const saved=sessionStorage.getItem(key);
    if(saved){ setTimeout(()=>window.scrollTo(0,parseInt(saved)),100); }
  }catch(e){}
  window.addEventListener('scroll',()=>{
    try{ sessionStorage.setItem(key, window.scrollY); }catch(e){}
  },{passive:true});
}

