/* ---------- 添加matrix动画样式 ---------- */
function injectMatrixStyle(){
  if(document.getElementById('matrix-style')) return;
  const style=document.createElement('style'); style.id='matrix-style';
  style.textContent=`@keyframes matrix{from{filter:hue-rotate(0) saturate(1)}to{filter:hue-rotate(90deg) saturate(1.8) brightness(1.15)}}@keyframes matrixbit{0%{transform:translateY(-20px);opacity:0}20%{opacity:1}100%{transform:translateY(100vh);opacity:0}}`;
  document.head.appendChild(style);
}

/* ---------- 点击波纹效果 ---------- */
function initRipple(){
  document.addEventListener('click', e=>{
    const el = e.target.closest('button,a,.card,.exp-card,.exp-start,.aec-btn,.cmd-cat,.filter-tag,.search-btn,.icon-btn,.side-link');
    if(!el) return;
    // 避免在搜索面板等特殊元素上添加
    if(el.closest('.search-mask')) return;
    const rect = el.getBoundingClientRect();
    const ripple = document.createElement('span');
    ripple.className='ripple-effect';
    const size = Math.max(rect.width, rect.height);
    ripple.style.width = ripple.style.height = size+'px';
    ripple.style.left = (e.clientX - rect.left - size/2)+'px';
    ripple.style.top = (e.clientY - rect.top - size/2)+'px';
    el.appendChild(ripple);
    setTimeout(()=>ripple.remove(), 600);
  });
}

/* ---------- 滚动时顶部导航solid状态 ---------- */
function initNavScroll(){
  const topbar = document.querySelector('.topbar');
  if(!topbar) return;
  function update(){
    topbar.classList.toggle('solid', window.scrollY > 20);
  }
  window.addEventListener('scroll', update, {passive:true});
  update();
}

